CREATE TABLE IF NOT EXISTS member(id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL, phone VARCHAR(30), memo VARCHAR(200), active BOOLEAN DEFAULT TRUE, sort_order INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dues_settings(id INT PRIMARY KEY, group_name VARCHAR(100), monthly_amount BIGINT DEFAULT 0, due_day INT DEFAULT 10, account_info VARCHAR(300), kakao_template VARCHAR(2000));
CREATE TABLE IF NOT EXISTS payment(id BIGINT AUTO_INCREMENT PRIMARY KEY, member_id BIGINT NOT NULL, year_month VARCHAR(7) NOT NULL, amount BIGINT DEFAULT 0, paid BOOLEAN DEFAULT FALSE, paid_at DATE, note VARCHAR(200), UNIQUE(member_id, year_month));
